const down = new Set(), pressed = new Set(), released = new Set();
addEventListener('keydown', (e) => { if (!down.has(e.code)) pressed.add(e.code); down.add(e.code); });
addEventListener('keyup',   (e) => { down.delete(e.code); released.add(e.code); });

function endFrame() { pressed.clear(); released.clear(); }   // 매 프레임 끝에 비운다

const rules = {
  idle:    { move: 'run', jump: 'air', attack: 'attack' },
  run:     { stop: 'idle', jump: 'air', attack: 'attack' },
  air:     { land: 'idle', attack: 'airAttack' },
  attack:  { done: 'idle' },      // 공격 중에는 이동 입력을 무시
};
state = rules[state]?.[event] ?? state;

if (pressed.has('Space')) jumpBuffer = 0.12;
jumpBuffer -= dt; coyote = grounded ? 0.1 : coyote - dt;
if (jumpBuffer > 0 && coyote > 0) { jump(); jumpBuffer = 0; coyote = 0; }
